// ─── Helpers used by step definitions ──────────────────────────────────

findTodoLi(title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) return li;
  }
  return null;
}

hasClass(el, className) {
  return el.classList.contains(className);
}

getTodos() {
  const data = this.localStorage.getItem('todos-shipshape');
  return data ? JSON.parse(data) : [];
}

setTodos(todos) {
  this.localStorage.setItem('todos-shipshape', JSON.stringify(todos));
}

renderTodos() {
  // Clear existing list
  const list = this.document.querySelector('.todo-list');
  if (!list) return;
  list.innerHTML = '';
  const todos = this.getTodos();
  for (const todo of todos) {
    const li = this.document.createElement('li');
    if (todo.completed) li.classList.add('completed');
    li.innerHTML = '<div class="view">' +
      '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
      '<label>' + todo.title.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</label>' +
      '<button class="destroy"></button></div>' +
      '<input class="edit" value="' + todo.title.replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '">';
    li.dataset.id = todo.id;
    list.appendChild(li);
  }
  // Toggle visibility of main and footer
  const main = this.document.querySelector('.main');
  const footer = this.document.querySelector('.footer');
  const todoCount = this.document.querySelector('.todo-count');
  const hasTodos = todos.length > 0;
  if (main) main.style.display = hasTodos ? 'block' : 'none';
  if (footer) footer.style.display = hasTodos ? 'block' : 'none';
  // Update count
  const activeCount = todos.filter(t => !t.completed).length;
  if (todoCount) {
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';
  }
  // Update toggle-all
  const toggleAll = this.document.getElementById('toggle-all');
  if (toggleAll) toggleAll.checked = hasTodos && todos.every(t => t.completed);
  // Route filter
  const hash = this.window.location.hash || '#/';
  this.applyFilter(hash);
}

applyFilter(hash) {
  const list = this.document.querySelector('.todo-list');
  if (!list) return;
  const todos = this.getTodos();
  const items = list.querySelectorAll('li');
  const route = hash.replace(/^#!/, '#/');
  for (let i = 0; i < items.length; i++) {
    const li = items[i];
    if (i < todos.length) {
      const todo = todos[i];
      if (route === '#/active' && todo.completed) { li.style.display = 'none'; }
      else if (route === '#/completed' && !todo.completed) { li.style.display = 'none'; }
      else { li.style.display = ''; }
    }
  }
  // Update filter link selected class
  const filters = this.document.querySelectorAll('.filters a');
  for (const a of filters) {
    const href = a.getAttribute('href');
    if (href === route) a.classList.add('selected');
    else a.classList.remove('selected');
  }
}

