(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shipshape';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  // ─── Model ──────────────────────────────────────────────────────────────────

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function setTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function genId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  }

  // ─── View ───────────────────────────────────────────────────────────────────

  function render() {
    var todos = getTodos();
    var list = document.querySelector('.todo-list');
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var todoCount = document.querySelector('.todo-count');
    var toggleAll = document.getElementById('toggle-all');
    var clearCompleted = document.querySelector('.clear-completed');

    // Clear list
    list.innerHTML = '';

    var route = getRoute();

    for (var i = 0; i < todos.length; i++) {
      var todo = todos[i];

      // Filter
      if (route === 'active' && todo.completed) continue;
      if (route === 'completed' && !todo.completed) continue;

      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');

      li.setAttribute('data-id', todo.id);
      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeAttr(todo.title) + '">';

      list.appendChild(li);
    }

    // Show/hide main & footer
    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Count
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';

    // Toggle-all
    toggleAll.checked = hasTodos && todos.every(function (t) { return t.completed; });

    // Clear completed
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';
  }

  function getRoute() {
    var hash = window.location.hash || '#/';
    hash = hash.replace(/^#!/, '#/');
    var match = hash.match(/^#\/(\w*)/);
    var route = match ? match[1] : '';
    updateFilterLinks(route);
    return route;
  }

  function updateFilterLinks(route) {
    var links = document.querySelectorAll('.filters a');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      var href = a.getAttribute('href');
      var linkRoute = href.replace(/^#\//, '');
      if (linkRoute === route || (!route && linkRoute === '')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function escapeAttr(str) {
    return str.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // ─── Controller ─────────────────────────────────────────────────────────────

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    var todos = getTodos();
    todos.push({ id: genId(), title: title, completed: false });
    setTodos(todos);
    render();
  }

  function removeTodo(id) {
    var todos = getTodos();
    var idx = -1;
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) { idx = i; break; }
    }
    if (idx === -1) return;
    todos.splice(idx, 1);
    setTodos(todos);
    render();
  }

  function toggleTodo(id) {
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    setTodos(todos);
    render();
  }

  function toggleAll(checked) {
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = checked;
    }
    setTodos(todos);
    render();
  }

  function clearCompleted() {
    var todos = getTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    setTodos(todos);
    render();
  }

  function updateTodo(id, title) {
    title = title.trim();
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        if (!title) {
          todos.splice(i, 1);
        } else {
          todos[i].title = title;
        }
        break;
      }
    }
    setTodos(todos);
    render();
  }

  // ─── Events ─────────────────────────────────────────────────────────────────

  document.addEventListener('DOMContentLoaded', function () {
    render();

    // New todo
    var newTodo = document.querySelector('.new-todo');
    newTodo.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
        addTodo(this.value);
        this.value = '';
      }
    });

    // List events via delegation
    var list = document.querySelector('.todo-list');
    list.addEventListener('change', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        if (li) toggleTodo(li.getAttribute('data-id'));
      }
    });

    list.addEventListener('click', function (e) {
      if (e.target.classList.contains('destroy')) {
        var li = e.target.closest('li');
        if (li) removeTodo(li.getAttribute('data-id'));
      }
    });

    list.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (!label) return;
      var li = label.closest('li');
      if (!li) return;
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
      editInput.value = editInput.value; // Reset to current title
    });

    list.addEventListener('keydown', function (e) {
      if (!e.target.classList.contains('edit')) return;
      var li = e.target.closest('li');
      if (!li) return;
      var id = li.getAttribute('data-id');

      if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
        e.target.blur();
      } else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) {
        li.classList.remove('editing');
        // Reset value to original title
        var todos = getTodos();
        for (var i = 0; i < todos.length; i++) {
          if (todos[i].id === id) {
            e.target.value = todos[i].title;
            break;
          }
        }
      }
    });

    list.addEventListener('blur', function (e) {
      if (!e.target.classList.contains('edit')) return;
      var li = e.target.closest('li');
      if (!li) return;
      li.classList.remove('editing');
      var id = li.getAttribute('data-id');
      updateTodo(id, e.target.value);
    }, true);

    // Toggle-all
    document.getElementById('toggle-all').addEventListener('change', function () {
      toggleAll(this.checked);
    });

    // Clear completed
    document.querySelector('.clear-completed').addEventListener('click', function () {
      clearCompleted();
    });

    // Hash change for routing
    window.addEventListener('hashchange', function () {
      render();
    });
  });
})();

